1. package certmagicgcs
2. 
3. import (
4. 	"context"
5. 	"fmt"
6. 	"os"
7. 
8. 	"github.com/caddyserver/caddy/v2"
9. 	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
10. 	"github.com/caddyserver/certmagic"
11. 	"github.com/google/tink/go/aead"
12. 	"github.com/google/tink/go/insecurecleartextkeyset"
13. 	"github.com/google/tink/go/keyset"
14. )
15. 
16. // Interface guards
17. var (
18. 	_ caddyfile.Unmarshaler  = (*CaddyStorageGCS)(nil)
19. 	_ caddy.StorageConverter = (*CaddyStorageGCS)(nil)
20. )
21. 
22. // CaddyStorageGCS implements a caddy storage backend for Google Cloud Storage.
23. type CaddyStorageGCS struct {
24. 	// BucketName is the name of the storage bucket.
25. 	BucketName string `json:"bucket-name"`
26. 	// EncryptionKeySet is the path of a json tink encryption keyset
27. 	EncryptionKeySet string `json:"encryption-key-set"`
28. }
29. 
30. func init() {
31. 	caddy.RegisterModule(CaddyStorageGCS{})
32. }
33. 
34. // CaddyModule returns the Caddy module information.
35. func (CaddyStorageGCS) CaddyModule() caddy.ModuleInfo {
36. 	return caddy.ModuleInfo{
37. 		ID: "caddy.storage.gcs",
38. 		New: func() caddy.Module {
39. 			return new(CaddyStorageGCS)
40. 		},
41. 	}
42. }
43. 
44. // CertMagicStorage returns a cert-magic storage.
45. func (s *CaddyStorageGCS) CertMagicStorage() (certmagic.Storage, error) {
46. 	config := StorageConfig{
47. 		BucketName: s.BucketName,
48. 	}
49. 
50. 	if len(s.EncryptionKeySet) > 0 {
51. 		f, err := os.Open(s.EncryptionKeySet)
52. 		if err != nil {
53. 			return nil, err
54. 		}
55. 		defer f.Close()
56. 
57. 		r := keyset.NewJSONReader(f)
58. 		// TODO: Add the ability to read an encrypted keyset / or envelope encryption
59. 		// see https://github.com/google/tink/blob/e5c9356ed471be08a63eb5ea3ad0e892544e5a1c/go/keyset/handle_test.go#L84-L86
60. 		// or https://github.com/google/tink/blob/master/docs/GOLANG-HOWTO.md
61. 		kh, err := insecurecleartextkeyset.Read(r)
62. 		if err != nil {
63. 			return nil, err
64. 		}
65. 		kp, err := aead.New(kh)
66. 		if err != nil {
67. 			return nil, err
68. 		}
69. 		config.AEAD = kp
70. 	}
71. 	return NewStorage(context.TODO(), config)
72. }
73. 
74. // Validate caddy gcs storage configuration.
75. func (s *CaddyStorageGCS) Validate() error {
76. 	if s.BucketName == "" {
77. 		return fmt.Errorf("bucket name must be defined")
78. 	}
79. 	return nil
80. }
81. 
82. // UnmarshalCaddyfile unmarshall caddy file.
83. func (s *CaddyStorageGCS) UnmarshalCaddyfile(d *caddyfile.Dispenser) error {
84. 	for d.Next() {
85. 		key := d.Val()
86. 		var value string
87. 
88. 		if !d.Args(&value) {
89. 			continue
90. 		}
91. 
92. 		switch key {
93. 		case "bucket-name":
94. 			s.BucketName = value
95. 		case "encryption-key-set":
96. 			s.EncryptionKeySet = value
97. 		}
98. 	}
99. 	return nil
100. }
