14. 	"google.golang.org/api/iterator"
15. 	"google.golang.org/api/option"
16. )
17. 
18. var (
19. 	// LockExpiration is the duration before which a Lock is considered expired
20. 	LockExpiration = 1 * time.Minute
21. 	// LockPollInterval is the interval between each check of the lock state.
22. 	LockPollInterval = 1 * time.Second
23. )
24. 
25. // Storage is a certmagic.Storage backed by a GCS bucket
26. type Storage struct {
27. 	bucket *storage.BucketHandle
28. 	aead   tink.AEAD
29. }
30. 
31. // Interface guards
32. var (
33. 	_ certmagic.Storage = (*Storage)(nil)
34. 	_ certmagic.Locker  = (*Storage)(nil)
35. )
36. 
37. type StorageConfig struct {
38. 	// BucketName is the name of the GCS storage Bucket
39. 	BucketName string
40. 	// ClientOptions GCS storage client options
41. 	ClientOptions []option.ClientOption
42. 	// AEAD for Authenticated Encryption with Additional Data
43. 	AEAD tink.AEAD
44. }
45. 
46. func NewStorage(ctx context.Context, config StorageConfig) (*Storage, error) {
47. 	client, err := storage.NewClient(ctx, config.ClientOptions...)
48. 	if err != nil {
49. 		return nil, fmt.Errorf("could not initialize storage client: %w", err)
50. 	}
51. 	bucket := client.Bucket(config.BucketName)
52. 	var kp tink.AEAD
53. 	if config.AEAD != nil {
54. 		kp = config.AEAD
55. 	} else {
56. 		kp = new(cleartext)
57. 	}
58. 	return &Storage{bucket: bucket, aead: kp}, nil
